UPDATE know_posts
content_url = #{contentUrl}, content_object_key = #{contentObjectKey}, content_etag = #{contentEtag}, content_size = #{contentSize}, content_sha256 = #{contentSha256}, update_time = #{updateTime}
WHERE id = #{id} AND creator_id = #{creatorId} AND status = 'draft'

UPDATE know_posts
title = #{title}, tag_id = #{tagId}, tags = #{tags}, img_urls = #{imgUrls}, visible = #{visible}, is_top = #{isTop}, description = #{description}, type = #{type}, update_time = #{updateTime}
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET status = 'published', publish_time = NOW(), update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET status = 'published',
    publish_time = #{publishedAt},
    publish_failed_reason = NULL,
    update_time = #{publishedAt}
WHERE id = #{id}
  AND creator_id = #{creatorId}
  AND status = 'publishing'
  AND publish_attempt_id = #{publishAttemptId}

UPDATE know_posts
SET status = 'publish_failed',
    publish_failed_reason = #{publishFailedReason},
    update_time = NOW()
WHERE id = #{id}
  AND creator_id = #{creatorId}
  AND status = 'publishing'
  AND publish_attempt_id = #{publishAttemptId}

