UPDATE know_posts
SET status = 'publishing',
    publish_failed_reason = NULL,
    update_time = NOW()
WHERE id = #{id}
  AND creator_id = #{creatorId}
  AND status = 'publish_failed'
  AND publish_attempt_id = #{publishAttemptId}

UPDATE know_posts
SET is_top = #{isTop}, update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET visible = #{visible}, update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET status = 'deleted', update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

mapper.select:
SELECT p.id, p.title, p.description, p.tags, p.img_urls AS imgUrls, u.avatar AS authorAvatar, u.nickname AS authorNickname, u.tags_json AS authorTagJson, p.publish_time AS publishTime, p.is_top AS isTop FROM know_posts p JOIN users u ON p.creator_id = u.id WHERE p.status = 'published' AND p.id IN
#{id}
AND ( p.visible = 'public' OR ( #{allowFollowers} AND #{currentUserId} IS NOT NULL AND p.visible = 'followers' AND EXISTS ( SELECT 1 FROM following f WHERE f.from_user_id = #{currentUserId} AND f.to_user_id = p.creator_id AND f.rel_status = 1 ) ) )

SELECT id
FROM know_posts

    status = 'published'

        AND id > #{cursorPostId}


ORDER BY id ASC
LIMIT #{limit}

SELECT id FROM know_posts
status = 'published' AND visible = 'public'
AND id > #{cursorPostId}
ORDER BY id ASC LIMIT #{limit}
